import subprocess


def grep_file(pattern: str, path: str) -> list[str]:
    proc = subprocess.run(["grep", "-e", pattern, "--", path], capture_output=True, text=True)
    if proc.returncode == 0:
        return proc.stdout.splitlines()
    if proc.returncode == 1:
        return []
    raise RuntimeError(proc.stderr.strip() or "grep failed with status %d" % proc.returncode)

