def test_roundtrip_levels_and_protocols():
    for level in (1, 6, 9):
        for proto in (2, 4, pickle.HIGHEST_PROTOCOL):
            for entry in ENTRIES:
                blob = zlib.compress(pickle.dumps(entry, protocol=proto), level)
                restored = restore_cache_entry(blob)
                assert isinstance(restored, dict)
                assert restored == entry


def test_types_are_preserved():
    entry = {"i": 1, "f": 1.0, "s": "1", "l": [1], "d": {"k": 1}}
    restored = restore_cache_entry(zlib.compress(pickle.dumps(entry)))
    assert type(restored["i"]) is int
    assert type(restored["f"]) is float
    assert type(restored["s"]) is str
    assert type(restored["l"]) is list
    assert type(restored["d"]) is dict


def test_large_entry():
