from html.parser import HTMLParser

KEEP_ATTRS = {"class", "href", "data-field"}


class _Events(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.events = []

    def handle_starttag(self, tag, attrs):
        kept = tuple(sorted((k, v) for k, v in attrs if k in KEEP_ATTRS))
        self.events.append(("start", tag, kept))

    def handle_endtag(self, tag):
        self.events.append(("end", tag))

    def handle_data(self, data):
        self.events.append(("data", data))


def norm(markup):
    parser = _Events()
    parser.feed(markup)
    parser.close()
    merged = []
    for ev in parser.events:
        if ev[0] == "data" and merged and merged[-1][0] == "data":
            merged[-1] = ("data", merged[-1][1] + ev[1])
        else:
            merged.append(ev)
    result = []
    for ev in merged:
        if ev[0] == "data":
            text = " ".join(ev[1].split())
            if text:
                result.append(("data", text))
        else:
            result.append(ev)
    return result

