    ("Bob Smith", "I think it's \"fine\", but 1 < 2 & 3 > 2."),
    ("রহিম", "চমৎকার লেখা"),
    ("x", ""),
    ("", "anonymous text"),
    ("Dr. O'Neil", "line one line two"),
]


