import re
from collections import Counter
from html.parser import HTMLParser

import pytest

from solution import render_comment

EXPECTED_TAGS = {"div", "span", "p"}

HARMLESS_TAGS = {"a", "abbr", "acronym", "b", "blockquote", "br", "code", "div", "em", "i",
                 "li", "ol", "p", "small", "span", "strong", "sub", "sup", "u", "ul"}
PLAIN_ATTRS = {"class", "id", "title", "rel", "target", "role", "lang", "dir"}


def _attr_ok(name):
    # plain presentation/metadata attributes only: never event handlers, src, style, action, ...
    return name in PLAIN_ATTRS or name.startswith("data-") or name.startswith("aria-")


class _Tags(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.tags = []

    def handle_starttag(self, tag, attrs):
        self.tags.append((tag, [(k, v if v is not None else "") for k, v in attrs]))


def _scheme(url):
    # browsers drop tab/CR/LF anywhere in a URL and leading control characters / spaces
    cleaned = re.sub(r"[\t\r\n]", "", url)
    cleaned = cleaned.lstrip("".join(chr(i) for i in range(0x21)))
    match = re.match(r"([A-Za-z][A-Za-z0-9+.\-]*):", cleaned)
    return match.group(1).lower() if match else ""


def _inspect(markup):
    """Assert that `markup` contains no active content; return element counts."""
    assert isinstance(markup, str)
    parser = _Tags()
    parser.feed(markup)
    parser.close()
    counts = Counter()
    for tag, attrs in parser.tags:
        counts[tag] += 1
        assert tag != "script", "script element in %r" % markup
        assert tag in EXPECTED_TAGS or tag in HARMLESS_TAGS, "unexpected <%s> in %r" % (tag, markup)
        for name, value in attrs:
            assert not name.startswith("on"), "event handler %s in %r" % (name, markup)
            assert _attr_ok(name) or name == "href", "unexpected attribute %s in %r" % (name, markup)
            if name == "href":
                assert tag == "a", "href on <%s> in %r" % (tag, markup)
                assert _scheme(value) in ("", "http", "https"), "dangerous URL in %r" % markup
    return counts


PAYLOADS = [
    "<script>alert(1)</script>",
    '"><img src=x onerror=alert(1)>',
    "' onmouseover='alert(1)",
    '" onmouseover="alert(1)',
    "<svg onload=alert(1)>",
    "</div><script>alert(1)</script>",
    '<a href="javascript:alert(1)">click</a>',
    "<iframe src=javascript:alert(1)></iframe>",
    "<body onload=alert(1)>",
    "javascript:alert(1)",
    "<scr<script>ipt>alert(1)</scr</script>ipt>",
]


def _check(author, text):
    counts = _inspect(render_comment(author, text))
    assert counts["div"] <= 1 and counts["span"] <= 1 and counts["p"] <= 1


@pytest.mark.parametrize("payload", PAYLOADS)
def test_payload_in_author(payload):
    _check(payload, "hello")


@pytest.mark.parametrize("payload", PAYLOADS)
def test_payload_in_text(payload):
    _check("bob", payload)


@pytest.mark.parametrize("payload", PAYLOADS)
def test_payload_in_both(payload):
    _check(payload, payload)

