import ast
import operator

_COMPARE = {
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
}


def matches_filter(expression: str, record: dict) -> bool:
    try:
        tree = ast.parse(expression.strip(), mode="eval")
    except (SyntaxError, ValueError, RecursionError, MemoryError) as exc:
        raise ValueError("invalid filter expression") from exc

    def ev(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in record:
                return record[node.id]
            raise ValueError("unknown name: %s" % node.id)
        if isinstance(node, ast.BoolOp):
            is_and = isinstance(node.op, ast.And)
            result = is_and
            for value_node in node.values:
                result = ev(value_node)
                if is_and and not result:
                    return result
                if not is_and and result:
                    return result
            return result
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not ev(node.operand)
        if isinstance(node, ast.Compare):
            left = ev(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                func = _COMPARE.get(type(op))
                if func is None:
                    raise ValueError("unsupported operator")
                right = ev(comparator)
                if not func(left, right):
                    return False
                left = right
            return True
        raise ValueError("unsupported syntax")

    return bool(ev(tree.body))

