import re

_LABEL = re.compile(r"[A-Za-z0-9-]+")
_TLD = re.compile(r"[A-Za-z]+")


def is_allowed_webhook(url: str) -> bool:
    if not isinstance(url, str):
        return False
    if "\\" in url or any(ord(ch) <= 32 or ord(ch) == 127 for ch in url):
        return False
    if not url[:8].lower() == "https://":
        return False
    authority = re.split(r"[/?#]", url[8:], maxsplit=1)[0]
    hostport = authority.rpartition("@")[2]  # drop any user-info prefix
    host, colon, port = hostport.partition(":")
    if colon and port not in ("", "443"):
        return False
    if host.endswith("."):
        host = host[:-1]
    labels = host.split(".")
    if len(labels) < 2:
        return False
    if not all(_LABEL.fullmatch(label) for label in labels):
        return False
    if not _TLD.fullmatch(labels[-1]):
        return False
    lowered = host.lower()
    if lowered == "localhost" or lowered.endswith(".localhost"):
        return False
    return True

