from urllib.parse import urlsplit


def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    try:
        parts = urlsplit(url)
        hostname = parts.hostname
    except ValueError:
        return False
    if parts.scheme.lower() not in ("http", "https"):
        return False
    if "@" in parts.netloc:  # user-info present
        return False
    if not hostname:
        return False
    host = hostname.lower()
    if host.endswith("."):
        host = host[:-1]
    return host in {entry.lower() for entry in allowed_hosts}

